"""One-time authoring source. Emits a static bank, not live generated questions.
Every row is an authored draft; arithmetic validation is not human approval.
"""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
rows=[]
def add(skill,family,difficulty,stem,options,answer,check,explanation,tip):
 rows.append(dict(id=f'quant-{len(rows)+13:03}',skill=skill,templateFamily=family,difficulty=difficulty,stem=stem,choices=options.split('|'),answer=answer,check=check,explanation=explanation,shortcut=tip))
S='sequence_additive'
add(S,'constant-subtraction',1,'What number comes next?  53, 46, 39, 32, …','18|23|25|27','25','32-7','Each term decreases by 7. Subtract 7 from 32 to get 25.','Test subtraction when a sequence decreases steadily.')
add(S,'decimal-addition',1,'What number comes next?  1.2, 1.6, 2.0, 2.4, …','2.6|2.8|3.0|3.2','2.8','2.4+0.4','Each term increases by 0.4. The next term is 2.4 + 0.4 = 2.8.','Think in tenths: 12, 16, 20, 24, then 28 tenths.')
add(S,'increasing-differences',2,'What number comes next?  4, 6, 10, 16, 24, …','30|32|34|36','34','24+10','The increases are 2, 4, 6, and 8. The next increase is 10, giving 34.','Write the differences before trying a complicated rule.')
add(S,'decreasing-differences',2,'What number comes next?  60, 49, 39, 30, 22, …','14|15|16|17','15','22-7','The amounts subtracted are 11, 10, 9, and 8. Subtract 7 next: 22 − 7 = 15.','A decreasing sequence can have shrinking gaps.')
add(S,'alternating-addition',2,'What number comes next?  8, 11, 16, 19, 24, …','25|27|29|32','27','24+3','The changes alternate between +3 and +5. After +5, use +3 to get 27.','Check whether the differences repeat in pairs.')
add(S,'interleaved-arithmetic',3,'What number comes next?  2, 20, 5, 18, 8, 16, …','10|11|13|14','11','8+3','The odd-position terms are 2, 5, 8, increasing by 3. The next term is in that group, so it is 11. The even-position terms decrease by 2.','Separate the odd and even positions into two smaller sequences.')
add(S,'fraction-addition',2,'What number comes next?  1/4, 3/4, 5/4, 7/4, …','8/4|9/4|10/4|11/4','9/4','7/4+1/2','The numerator increases by 2 while the denominator stays 4. The next term is 9/4.','With equal denominators, look at the numerators first.')
add(S,'missing-additive-term',1,'What number fills the blank?  14, 23, __, 41, 50','30|31|32|34','32','23+9','The sequence adds 9 each time: 14, 23, 32, 41, 50.','Check your missing term against both neighbors.')
add(S,'square-gaps',2,'What number comes next?  5, 8, 13, 20, 29, …','38|39|40|41','40','29+11','The gaps are 3, 5, 7, and 9. The next odd-number gap is 11, so the next term is 40.','Consecutive odd gaps often appear in square-like sequences.')
add(S,'growing-subtraction',2,'What number comes next?  50, 48, 44, 38, 30, …','18|20|22|24','20','30-10','Subtract 2, then 4, then 6, then 8. Subtract 10 next to get 20.','Keep the direction of the change: the gaps grow, but the terms fall.')
add(S,'alternating-direction',2,'What number comes next?  12, 19, 15, 22, 18, …','21|23|25|29','25','18+7','The rule alternates +7 and −4. The last step was −4, so add 7 next: 25.','Label each step with its sign to spot an alternating rule.')
add(S,'sum-previous-two',2,'What number comes next?  2, 3, 5, 8, 13, …','18|20|21|26','21','8+13','Starting with the third term, each term is the sum of the two before it. Thus 8 + 13 = 21.','If one-step differences do not fit, try adding neighboring terms.')
add(S,'additive-position',2,'A sequence starts at 6 and adds 4 each time. What is its eighth term?','30|32|34|38','34','6+7*4','There are seven increases between the first and eighth terms. Compute 6 + 7 × 4 = 34.','The nth term is n − 1 steps from the first term.')
add(S,'decreasing-step-size',2,'What number comes next?  3, 12, 20, 27, 33, …','37|38|39|40','38','33+5','The increases are 9, 8, 7, and 6. Add 5 next to get 38.','A growing sequence can have shrinking positive gaps.')
add(S,'signed-addition',2,'What number comes next?  −11, −6, −1, 4, …','5|7|9|11','9','4+5','The sequence adds 5 each time, even as it crosses zero. The next term is 9.','Treat crossing zero like any other addition step.')
add(S,'three-step-cycle',3,'What number comes next?  4, 6, 9, 13, 15, 18, …','20|21|22|24','22','18+4','The increases repeat +2, +3, +4. After +2 and +3, add 4 to get 22.','Not every repeating pattern has only two steps.')
S='sequence_multiplicative'
add(S,'tripling',1,'What number comes next?  2, 6, 18, 54, …','108|126|162|216','162','54*3','Each term is multiplied by 3. Thus 54 × 3 = 162.','Check ratios when numbers grow much faster than constant addition.')
add(S,'division-by-three',1,'What number comes next?  405, 135, 45, 15, …','3|5|9|12','5','15/3','Each term is divided by 3. The next term is 15 ÷ 3 = 5.','Verify the same divisor works for every neighboring pair.')
add(S,'multiply-add',2,'What number comes next?  2, 5, 11, 23, …','45|46|47|48','47','23*2+1','Each term is doubled, then increased by 1. So 23 × 2 + 1 = 47.','Try a small adjustment after multiplying when simple doubling nearly works.')
add(S,'multiply-subtract',2,'What number comes next?  4, 11, 32, 95, …','190|284|285|286','284','95*3-1','Each term is multiplied by 3, then reduced by 1. The next term is 285 − 1 = 284.','Check the multiply-and-adjust rule on more than one pair.')
add(S,'decimal-halving',2,'What number comes next?  6, 3, 1.5, 0.75, …','0.25|0.325|0.375|0.5','0.375','0.75/2','Each term is half the previous one. Half of 0.75 is 0.375.','Halving 75 hundredths gives 375 thousandths.')
add(S,'alternating-ratios',2,'What number comes next?  1, 2, 6, 12, 36, …','48|60|72|108','72','36*2','The multipliers alternate ×2, ×3. After ×3, multiply by 2 to get 72.','Write the ratio above each gap to reveal a repeating pair.')
add(S,'increasing-multipliers',3,'What number comes next?  1, 2, 6, 24, 120, …','240|360|600|720','720','120*6','The multipliers are 2, 3, 4, and 5. Multiply by 6 next: 720.','The multiplier itself can form a counting sequence.')
add(S,'powers-of-ten',1,'What number comes next?  0.07, 0.7, 7, 70, …','77|140|700|7000','700','70*10','Each term is multiplied by 10. Thus 70 becomes 700.','Keep track of place value when multiplying by 10.')
add(S,'missing-geometric-term',2,'What number fills the blank?  7, 28, __, 448','56|84|112|224','112','28*4','The multiplier is 4. The missing term is 28 × 4 = 112, and 112 × 4 = 448.','Check the multiplier on both sides of the blank.')
add(S,'fraction-tripling',2,'What number comes next?  1/9, 1/3, 1, 3, …','4|6|9|12','9','3*3','Each term is multiplied by 3, including the fractions. After 3 comes 9.','Simplify fractions to see a constant multiplier.')
add(S,'three-halves-ratio',3,'What number comes next?  8, 12, 18, 27, …','36|39|40.5|54','40.5','27*1.5','Each term is multiplied by 1.5. Add half of 27 to itself: 27 + 13.5 = 40.5.','Multiplying by 1.5 means adding half the number.')
add(S,'geometric-position',2,'A sequence begins with 3 and doubles each time. What is its sixth term?','48|72|96|192','96','3*2**5','The six terms are 3, 6, 12, 24, 48, and 96. Five doublings are needed.','Count terms carefully; the first term does not require a doubling.')
add(S,'divide-add',3,'Use the repeating rule “divide by 2, then add 3.” What follows 30, 18, 12, 9?','6|7.5|8|9','7.5','9/2+3','Apply both steps to 9: 9 ÷ 2 = 4.5, then 4.5 + 3 = 7.5.','Do not round halfway through a rule; a decimal result can be correct.')
add(S,'alternating-geometric-branches',3,'What number comes next?  2, 3, 4, 9, 8, 27, …','12|16|54|81','16','8*2','Odd-position terms double: 2, 4, 8, then 16. Even-position terms triple: 3, 9, 27.','Read every other term when a single multiplier does not fit.')
S='numeric_comparison'
add(S,'mixed-comparison',1,'Which value is smallest?','0.45|1/2|48%|0.405','0.405','min(0.45,1/2,48/100,0.405)','The values are 0.450, 0.500, 0.480, and 0.405. The smallest is 0.405.','Align decimal places; extra digits do not automatically mean a larger value.')
add(S,'common-numerator',2,'Which fraction is greatest?','5/8|5/6|5/9|5/12','5/6','max(5/8,5/6,5/9,5/12)','With the same positive numerator, the smallest positive denominator gives the greatest fraction. That is 5/6.','Equal numerators: fewer pieces means each piece is larger.')
add(S,'fraction-benchmark',2,'Which fraction is greater than 1/2?','4/9|5/12|7/13|6/13','7/13','7/13','Half of 13 is 6.5, and 7 is larger than 6.5. Each other numerator is less than half its denominator.','Double each numerator and compare it with the denominator.')
add(S,'percent-of-comparison',2,'Which quantity is greatest?','20% of 90|30% of 70|25% of 80|10% of 190','30% of 70','max(20/100*90,30/100*70,25/100*80,10/100*190)','The quantities are 18, 21, 20, and 19. The greatest is 21, from 30% of 70.','Find 10% first for multiples of 10%; divide by 4 for 25%.')
add(S,'distance-to-one',2,'Which value is closest to 1?','7/8|0.92|95%|1.08','95%','95/100','The distances from 1 are 0.125, 0.08, 0.05, and 0.08. The smallest distance is 0.05.','Compare the gap to 1, not just the values themselves.')
add(S,'decimal-place-value',1,'Which value is greatest?','0.607|0.67|0.067|0.617','0.67','max(0.607,0.67,0.067,0.617)','Write 0.67 as 0.670. Comparing thousandths gives 607, 670, 67, and 617, so 0.670 is greatest.','Pad with zeros on the right to make place values line up.')
add(S,'negative-comparison',2,'Which number is greatest?','−0.8|−1/2|−0.65|−0.9','−1/2','max(-0.8,-1/2,-0.65,-0.9)','All choices are negative. −1/2 equals −0.5, which is closest to zero and therefore greatest.','Among negative numbers, the one closest to zero is greatest.')
add(S,'equivalent-percent',1,'Which percentage equals 7/20?','28%|30%|35%|40%','35%','7/20','Multiply numerator and denominator by 5: 7/20 = 35/100 = 35%.','A denominator of 20 scales to 100 by multiplying by 5.')
add(S,'geometry-area-comparison',2,'A square has side length 6. A rectangle has length 8 and width 4. By how much is the square’s area greater?','2|4|8|12','4','6*6-8*4','The square’s area is 36 and the rectangle’s area is 32. Their difference is 4 square units.','Calculate area, not perimeter: multiply the two dimensions.')
add(S,'geometry-perimeter-comparison',2,'A rectangle is 9 units long and 3 units wide. A square has the same perimeter. What is the square’s side length?','3|6|9|12','6','2*(9+3)/4','The rectangle’s perimeter is 2 × (9 + 3) = 24. Divide by the square’s four equal sides to get 6.','Equal perimeter does not mean equal area.')
add(S,'fraction-gap',2,'How much greater is 3/4 than 2/3?','1/12|1/6|1/4|5/12','1/12','3/4-2/3','Use twelfths: 3/4 = 9/12 and 2/3 = 8/12. Their difference is 1/12.','Use the least common denominator to compare fractions exactly.')
add(S,'ratio-comparison',2,'Which ratio has the same value as 3:5?','6:15|9:15|12:25|15:20','9:15','3/5','Multiplying both parts of 3:5 by 3 gives 9:15. The other ratios simplify to different values.','Scale both parts by the same factor.')
add(S,'squared-fraction-comparison',3,'Which value is smallest?','(1/2)²|1/3|0.3|28%','(1/2)²','min((1/2)**2,1/3,0.3,28/100)','Squaring 1/2 gives 1/4 = 0.25. This is less than 1/3, 0.3, and 0.28.','A positive fraction below 1 becomes smaller when squared.')
add(S,'geometry-scaled-area',2,'A square’s side length increases from 3 to 6 units. What is the ratio of its new area to its old area?','2:1|3:1|4:1|6:1','4:1','6**2/3**2','The old area is 9 and the new area is 36. The ratio 36:9 simplifies to 4:1.','Doubling a length multiplies the corresponding area by 4.')
add(S,'fraction-distance-half',3,'Which fraction is closest to 1/2?','5/8|4/9|7/12|3/7','4/9','4/9','The distances from 1/2 are 1/8, 1/18, 1/12, and 1/14. The smallest distance is 1/18, from 4/9.','Compare each fraction’s distance from the benchmark using exact fractions.')
add(S,'geometry-angle-comparison',2,'A triangle has angles of 45° and 65°. By how many degrees does its third angle exceed its smallest angle?','20|25|30|70','25','180-45-65-45','The third angle is 180 − 45 − 65 = 70°. The smallest is 45°, so the difference is 25°.','Find the missing angle first, then answer the comparison being asked.')
S='number_manipulation'
add(S,'ten-percent',1,'What is 10% of 350?','3.5|30|35|50','35','350/10','Ten percent is one tenth. Dividing 350 by 10 gives 35.','Move the decimal one place left to find 10%.')
add(S,'percent-decomposition',2,'What is 15% of 80?','8|10|12|16','12','15/100*80','Ten percent of 80 is 8 and 5% is 4. Add them to get 12.','Split 15% into 10% plus 5%.')
add(S,'reverse-percent',2,'18 is 30% of what number?','54|60|72|90','60','18/(30/100)','If 30% is 18, then 10% is 6 and 100% is 60.','Scale down to 10%, then scale up to 100%.')
add(S,'discount',2,'A book costs $40 before a 20% discount. What is the sale price in dollars?','8|20|30|32','32','40*(1-20/100)','Twenty percent of 40 is 8. Subtract the discount: 40 − 8 = 32.','The sale price is 80% of the original, not the discount amount.')
add(S,'ratio-total',2,'Red and blue counters are in a ratio of 2:3. There are 35 counters in total. How many are blue?','14|15|21|25','21','35/(2+3)*3','There are 5 equal ratio parts. Each part is 35 ÷ 5 = 7 counters, and blue uses 3 parts: 21.','Add the ratio parts before dividing the total.')
add(S,'average-missing',2,'The average of 12, 16, and a third number is 15. What is the third number?','15|16|17|19','17','15*3-12-16','The three numbers must total 45. Subtract 12 and 16: 45 − 28 = 17.','Convert an average into a total before finding a missing value.')
add(S,'order-of-operations',1,'What is 7 + 3 × 8?','31|56|80|88','31','7+3*8','Multiply first: 3 × 8 = 24. Then add 7 to get 31.','Multiplication comes before addition unless parentheses change the order.')
add(S,'distributive-mental',2,'What is 19 × 6?','104|110|114|124','114','19*6','Use 20 × 6 = 120, then subtract one group of 6: 114.','Round to a convenient number, then compensate.')
add(S,'fraction-of-quantity',2,'What is 3/8 of 64?','8|16|24|32','24','3/8*64','One eighth of 64 is 8. Three eighths is 3 × 8 = 24.','Divide by the denominator first when it divides evenly.')
add(S,'unit-rate',2,'Five identical notebooks cost $15. How many dollars do eight notebooks cost?','18|21|24|40','24','15/5*8','Each notebook costs 15 ÷ 5 = 3 dollars. Eight cost 8 × 3 = 24 dollars.','Find the price of one item before scaling.')
add(S,'consecutive-integers',2,'Three consecutive whole numbers have a sum of 72. What is the largest?','23|24|25|26','25','72/3+1','Their middle number is 72 ÷ 3 = 24. The numbers are 23, 24, and 25.','For three consecutive numbers, the average is the middle one.')
add(S,'remainder',2,'What is the remainder when 157 is divided by 6?','1|2|3|5','1','157%6','The greatest multiple of 6 not exceeding 157 is 156. Subtract to get a remainder of 1.','Use the nearest lower multiple of the divisor.')
add(S,'proportional-sum',3,'One number is three times another. Their sum is 52. What is the smaller number?','12|13|17|39','13','52/(3+1)','The smaller number is one part and the larger is three parts. Four parts total 52, so one part is 13.','Translate “three times” into 3 parts plus 1 part.')
add(S,'difference-equation',3,'Two numbers differ by 8 and have a sum of 46. What is the larger number?','19|23|27|31','27','(46+8)/2','Their average is 23. Each number is 4 away from the average, so the larger is 27.','Add half the difference to the average.')
add(S,'percent-increase',2,'A value rises from 40 to 50. What is the percentage increase?','10%|20%|25%|40%','25%','(50-40)/40','The increase is 10. Relative to the original 40, that is 10/40 = 1/4 = 25%.','Divide by the original value, not the new value.')
add(S,'successive-fractions',3,'A tank is 3/4 full. Half of the water is removed. What fraction of the whole tank is still filled?','1/4|3/8|1/2|5/8','3/8','3/4*1/2','Half of the water remains, so take half of 3/4: 3/4 × 1/2 = 3/8.','“Half of” means multiply by 1/2, not subtract 1/2 of the whole tank.')
S='symbolic_pattern'
add(S,'mapping',1,'A machine multiplies an input by 4, then subtracts 2. What output does an input of 5 produce?','12|18|20|22','18','5*4-2','Multiply 5 by 4 to get 20, then subtract 2 to get 18.','Translate a machine rule into two short steps.')
add(S,'inverse-mapping',2,'A machine doubles an input, then adds 5. Its output is 23. What was the input?','7|9|11|14','9','(23-5)/2','Undo +5 first: 23 − 5 = 18. Then undo doubling: 18 ÷ 2 = 9.','Reverse both the operations and their order.')
add(S,'symbol-operation',2,'Define a ◇ b to mean a × b + a. What is 3 ◇ 4?','10|12|15|16','15','3*4+3','Substitute a = 3 and b = 4: 3 × 4 + 3 = 15.','Read the definition carefully; the symbol is not ordinary multiplication.')
add(S,'square-mapping',2,'A machine squares its input, then adds 2. What is the output for an input of 7?','16|47|49|51','51','7**2+2','Squaring 7 gives 49. Adding 2 gives 51.','Squaring means multiplying the number by itself, not doubling it.')
add(S,'symbol-values',2,'If △ = 4 and ○ = 7, what is 3 × △ + ○?','19|21|28|33','19','3*4+7','Replace the symbols: 3 × 4 + 7 = 12 + 7 = 19.','Substitute numbers, then follow the usual operation order.')
add(S,'shared-symbol-equations',2,'If □ + □ = 18 and □ + △ = 14, what is △?','4|5|7|9','5','14-18/2','Two squares total 18, so each square is 9. Then triangle = 14 − 9 = 5.','Find the repeated symbol first.')
add(S,'row-sum-rule',2,'In each row, the third number is the sum of the first two: (4, 7, 11), (6, 8, 14), (9, 5, ?). What replaces ?','4|12|14|45','14','9+5','Apply the stated row rule: 9 + 5 = 14.','Apply the same rule to the same positions in every row.')
add(S,'row-product-rule',2,'Each row follows the rule “first × second − 1 = third”: (3, 4, 11), (2, 7, 13), (5, 6, ?). What replaces ?','10|29|30|31','29','5*6-1','Multiply 5 by 6 to get 30, then subtract 1 to get 29.','Keep the adjustment after multiplication.')
add(S,'nested-symbol',3,'Define f(n) = 2n + 1. What is f(f(3))?','7|13|15|16','15','2*(2*3+1)+1','First f(3) = 7. Apply the same rule to that result: f(7) = 15.','Work from the inside outward, one function at a time.')
add(S,'two-machine-composition',3,'Machine A adds 4. Machine B multiplies by 3. An input of 5 goes through A, then B. What is the output?','19|23|27|31','27','(5+4)*3','Machine A changes 5 to 9. Machine B changes 9 to 27.','The order matters: add before multiplying in this pipeline.')
add(S,'digit-mapping',2,'A code assigns a two-digit number the sum of its digits: 34 → 7 and 62 → 8. What is the code for 85?','3|13|40|58','13','8+5','Add the digits of 85: 8 + 5 = 13.','Use the digits as separate numbers when the rule says digit sum.')
add(S,'weighted-symbol',3,'If ○ + ○ + △ = 17 and ○ = 6, what is 2 × △?','5|10|11|22','10','2*(17-2*6)','The two circles contribute 12, leaving triangle = 5. Twice the triangle is 10.','Find the symbol value, then compute the expression actually requested.')
add(S,'noncommutative-symbol',3,'Define a ★ b = 2a + b. How much greater is 7 ★ 3 than 3 ★ 7?','0|4|7|10','4','(2*7+3)-(2*3+7)','7 ★ 3 = 17, while 3 ★ 7 = 13. Their difference is 4.','Do not assume a custom operation gives the same result when reversed.')
add(S,'inverse-square-mapping',2,'A machine squares a positive whole-number input, then subtracts 4. Its output is 32. What is its input?','4|6|8|18','6','6','Add 4 back to get 36. The positive whole number whose square is 36 is 6.','Undo the subtraction before taking the positive square root.')
S='odd_one_out'
add(S,'prime-classification',2,'Which number is not prime?','11|17|21|23','21','21','21 = 3 × 7, so it has factors other than 1 and itself. The other choices are prime.','For small numbers, check divisibility by 2, 3, and 5 first.')
add(S,'cube-classification',2,'Which number is not a perfect cube?','8|27|64|100','100','100','8 = 2³, 27 = 3³, and 64 = 4³. But 100 lies between 4³ = 64 and 5³ = 125.','Remember a few small cubes rather than confusing cubes with squares.')
add(S,'power-of-two-classification',2,'Which number is not a power of 2?','16|32|48|64','48','48','Powers of 2 include 16, 32, and 64. The number 48 falls between 32 and 64.','Build powers of 2 by repeated doubling.')
add(S,'factor-classification',1,'Which number is not a factor of 36?','4|6|8|9','8','8','36 divides evenly by 4, 6, and 9. Dividing by 8 leaves a remainder.','A factor must divide the number with no remainder.')
add(S,'divisibility-nine',2,'Which number is not divisible by 9?','72|108|126|145','145','145','The digit sums are 9, 9, 9, and 10. Only 145 has a digit sum not divisible by 9.','Use the digit-sum test for divisibility by 9.')
add(S,'fraction-equivalence-classification',2,'Which value is not equal to 3/4?','0.75|75%|6/8|9/16','9/16','9/16','0.75, 75%, and 6/8 all equal 3/4. But 9/16 is 0.5625.','Convert each choice to a common fraction or decimal.')
add(S,'divisibility-four',1,'Which number is not a multiple of 4?','28|36|46|52','46','46','28, 36, and 52 are 4 times 7, 9, and 13. The number 46 is not divisible by 4.','Being even is necessary but not sufficient for being a multiple of 4.')
add(S,'fraction-below-one',1,'Which fraction is not less than 1?','3/5|7/9|8/7|11/12','8/7','8/7','8/7 has a numerator larger than its positive denominator, so it is greater than 1. The others are below 1.','Compare numerator and denominator before calculating a decimal.')
add(S,'remainder-classification',2,'Which number does not leave a remainder of 1 when divided by 5?','16|21|27|31','27','27','16, 21, and 31 are each 1 more than a multiple of 5. The number 27 is 2 more than 25.','Look for numbers ending in 1 or 6 when the remainder after division by 5 is 1.')
add(S,'square-successor',2,'Which number is not one more than a perfect square?','10|17|26|35','35','35','Subtract 1 from each choice to get 9, 16, 25, and 34. Only 34 is not a perfect square.','Undo the stated adjustment before checking the category.')
add(S,'fraction-reducibility',2,'Which fraction is already in simplest form?','6/9|8/28|7/15|10/25','7/15','7/15','7 and 15 have no common factor greater than 1. The other fractions share factors 3, 4, and 5 respectively.','A fraction is simplest when numerator and denominator have no common factor above 1.')
add(S,'divisibility-both',2,'Which number is not divisible by both 3 and 4?','24|36|54|60','54','54','24, 36, and 60 are multiples of 12. The number 54 is divisible by 3 but not by 4.','Divisible by both 3 and 4 means divisible by their least common multiple, 12.')
assert len(rows)==88,len(rows)
(ROOT/'content/authored-drafts.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
# Preserve explicit authored choice order; balance answer positions by deterministic rotation.
new=[]
for i,r in enumerate(rows):
 options=r['choices']; target=i%4; at=options.index(r['answer']); shift=(at-target)%4
 options=options[shift:]+options[:shift]
 new.append({k:r[k] for k in ['id','skill','templateFamily','difficulty','stem']}|{'section':'quantitative','reviewStatus':'pending_human_review','sourceType':'original_draft','choices':options,'guide':{'correctChoiceId':'ABCD'[target],'explanation':r['explanation'],'shortcut':r['shortcut']}})
(ROOT/'src/data/questions.expanded.json').write_text(json.dumps(new,ensure_ascii=False,indent=2)+'\n')
print('Authored',len(new),'new questions')
